import { readdir, readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../../knowledge/packs');
let cache=null;
export async function loadKnowledgePacks({refresh=false}={}){if(cache&&!refresh)return structuredClone(cache);const files=(await readdir(ROOT)).filter(f=>f.endsWith('.json')).sort();const packs=[];for(const file of files)packs.push(JSON.parse(await readFile(path.join(ROOT,file),'utf8')));cache=packs;return structuredClone(packs);}
export function validateKnowledgePacks(packs,capabilities){const errors=[];const ids=new Set();const capabilityIds=new Set(capabilities.map(c=>c.capabilityId));for(const pack of packs){if(ids.has(pack.id))errors.push(`duplicate pack: ${pack.id}`);ids.add(pack.id);if(pack.loadingPolicy!=='references-only-progressive-disclosure')errors.push(`${pack.id}: unsafe loading policy`);if(!pack.sources?.some(s=>['official','vendor','standards-body','local'].includes(s.authority)))errors.push(`${pack.id}: no authoritative source`);for(const id of pack.capabilities??[])if(!capabilityIds.has(id))errors.push(`${pack.id}: unknown capability ${id}`);for(const source of pack.sources??[]){if(!source.revision)errors.push(`${pack.id}: unpinned source ${source.id}`);if(source.license?.mode!=='link-only'&&source.license?.mode!=='vendor-allowed')errors.push(`${pack.id}: invalid license mode ${source.id}`);}}for(const capability of capabilities)if(!ids.has(capability.knowledgePackId))errors.push(`${capability.capabilityId}: missing knowledge pack ${capability.knowledgePackId}`);return{errors,count:packs.length};}
